package com.saumyasolar.repo;
import com.saumyasolar.domain.Invoice;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;import java.util.*;import java.util.UUID;
public interface InvoiceRepository extends JpaRepository<Invoice,UUID>{List<Invoice> findByTenantIdOrderByCreatedAtDesc(UUID tenantId);Optional<Invoice> findByIdAndTenantId(UUID id,UUID tenantId);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select i from Invoice i where i.id=:id and i.tenantId=:tenantId") Optional<Invoice> findForUpdate(@Param("id") UUID id,@Param("tenantId") UUID tenantId);Optional<Invoice> findByOrderIdAndTenantId(UUID orderId,UUID tenantId);long countByTenantIdAndFiscalYear(UUID tenantId,String fiscalYear);}
